  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "GSK1322322, a structurally related oral drug with an N-aryl piperazine and aminopyrimidine core, showed 77% absolute oral bioavailability in healthy volunteers after a meal, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Linezolid demonstrated 100% absolute oral bioavailability at an oral dose of 375 mg in patients, supporting that small heterocyclic oral drugs can achieve complete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone ER, a heterocyclic CNS drug, had 28% absolute oral bioavailability in healthy volunteers, which is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Rifapentine showed 70% absolute oral bioavailability after a single 600 mg oral dose in healthy adult volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Ketanserin had 46.8% absolute oral bioavailability in healthy male subjects, supporting high F for a moderately cleared heterocyclic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Apalutamide had approximately 100% absolute oral bioavailability in a phase 1 microtracer study, supporting high F for an oral small-molecule drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Tacrolimus oral bioavailability is approximately 20–25%, at the threshold but still supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Praziquantel showed 27.2% oral bioavailability in patients with hepatic disease, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: palbociclib is expected to have absolute oral bioavailability ≥20%, consistent with its recognized clinical F of about 46% and with uniformly supportive human bioavailability data from structurally similar oral drugs.",
  "evidence_gaps": [
    "No direct palbociclib bioavailability record is included in the supplied evidence set.",
    "Most records are from different drug classes; transferability relies on shared oral drug-like features rather than exact scaffold matches."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

